// Pull the fields we care about out of a raw Wazuh alert.
// Wazuh stores the source IP in different places depending on the log type.
const a = $json.body;
const d = a.data || {};
const srcip = d.srcip || d.src_ip || d.win?.eventdata?.ipAddress || null;

// RFC1918 / loopback / link-local addresses can't be looked up publicly
const isPrivate = (ip) =>
  /^(10\.|127\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|169\.254\.)/.test(ip) || ip === '::1' || ip === '-';

return { json: {
  alertId: a.id,
  time: a.timestamp,
  ruleId: a.rule?.id,
  level: Number(a.rule?.level ?? 0),
  description: a.rule?.description ?? 'Unknown rule',
  groups: a.rule?.groups ?? [],
  mitre: a.rule?.mitre?.id ?? [],
  agent: a.agent?.name ?? 'unknown',
  srcip,
  srcuser: d.srcuser || d.dstuser || d.win?.eventdata?.targetUserName || null,
  log: a.full_log ?? '',
  publicIp: !!srcip && !isPrivate(srcip),
} };

// The normalised alert (reached back past the IP lookup)
const alert = $('Normalise Alert').item.json;
// Geo data only exists if the alert went through "Lookup IP" successfully
const geo = $json.status === 'success' ? $json : null;

const HOME = ($env.HOME_COUNTRIES || 'United Kingdom').split(',').map(s => s.trim());

// --- Scoring rules (tune these) ---
let score = alert.level * 4;                 // Wazuh level 0-15  ->  0-60
const reasons = [`Wazuh level ${alert.level}`];

if (geo) {
  if (geo.proxy)   { score += 25; reasons.push('proxy / VPN / Tor'); }
  if (geo.hosting) { score += 15; reasons.push('datacenter / hosting'); }
  if (!HOME.includes(geo.country)) { score += 10; reasons.push(`outside home countries (${geo.country})`); }
} else if (alert.srcip && !alert.publicIp) {
  reasons.push('internal source IP');
}
if (alert.groups.includes('attack')) { score += 10; reasons.push('rule group: attack'); }

score = Math.min(score, 100);
const severity = score >= 70 ? 'high' : score >= 40 ? 'medium' : 'low';

// Telegram uses HTML formatting, so escape anything that came from logs
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return { json: {
  ...alert,
  country: geo?.country ?? null,
  isp: geo?.isp ?? null,
  score,
  severity,
  reasons,
  safe: {
    description: esc(alert.description),
    agent: esc(alert.agent),
    user: esc(alert.srcuser),
    isp: esc(geo?.isp),
    log: esc(alert.log.slice(0, 300)),
  },
} };

// Suppress repeats: same source (IP, or agent if no IP) + same rule within the window.
// Workflow static data is only saved on production (published) runs, not editor test runs.
const WINDOW_MIN = 10;
const memory = $getWorkflowStaticData('global');
memory.seen = memory.seen || {};
const now = Date.now();

// Forget entries older than the window
for (const [key, t] of Object.entries(memory.seen)) {
  if (now - t > WINDOW_MIN * 60 * 1000) delete memory.seen[key];
}

return $input.all().map((item) => {
  const a = item.json;
  const key = `${a.srcip ?? a.agent}|${a.ruleId}`;
  const duplicate = key in memory.seen;
  if (!duplicate) memory.seen[key] = now;
  return { json: { ...a, duplicate } };
});

